import ctypes
import os
import math

# Load the libraries
ctypes.CDLL('/usr/local/gsl/lib/libgslcblas.so', mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so')

# Define the function prototype
# double gsl_cdf_logistic_Pinv(const double P, const double a);
gsl.gsl_cdf_logistic_Pinv.argtypes = [ctypes.c_double, ctypes.c_double]
gsl.gsl_cdf_logistic_Pinv.restype = ctypes.c_double

def inverse_logistic_cdf(P, a):
    """Compute the inverse CDF for the logistic distribution using GSL."""
    if P == 0.0:
        return float('-inf')
    elif P == 1.0:
        return float('inf')
    elif P < 0.0 or P > 1.0:
        raise ValueError("Probability P must be in the range [0, 1].")
    else:
        return gsl.gsl_cdf_logistic_Pinv(P, a)

def assert_test():
    # Test cases
    assert inverse_logistic_cdf(0.5, 1.0) == 0.0, "Test case 1 failed"
    assert inverse_logistic_cdf(0.0, 1.0) == float('-inf'), "Test case 2 failed"
    assert inverse_logistic_cdf(1.0, 1.0) == float('inf'), "Test case 3 failed"
    assert abs(inverse_logistic_cdf(0.25, 2.0) - (-2.0 * math.log(3))) < 1e-9, "Test case 4 failed"
    assert abs(inverse_logistic_cdf(0.75, 2.0) - (2.0 * math.log(3))) < 1e-9, "Test case 5 failed"
    try:
        inverse_logistic_cdf(-0.1, 1.0)
    except ValueError as e:
        assert str(e) == "Probability P must be in the range [0, 1].", "Test case 6 failed"
    try:
        inverse_logistic_cdf(1.1, 1.0)
    except ValueError as e:
        assert str(e) == "Probability P must be in the range [0, 1].", "Test case 7 failed"

if __name__ == "__main__":
    assert_test()
